mapper.select:


    and kind = #{kind}
    and source = #{source}
    and user_name like concat('%', #{userName}, '%')
    and device_id = #{deviceId}
    and host_name like concat('%', #{hostName}, '%')
    and command like concat('%', #{command}, '%')
    and risk = #{risk}
    and decision = #{decision}
    and date_format(occurred_at,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
    and date_format(occurred_at,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')

order by occurred_at desc, audit_id desc
